using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Rendering.Universal;

// Rendered settlements, original ship silhouettes, preview dioramas and real stellar collectors.
public sealed class CivilizationScene : MonoBehaviour {
 sealed class DistrictView {public CivilizationModel.District data;public Transform root,rocket;}
 DefenseGame game;FrontierArt art;PlanetExpedition ground;CivilizationModel state;float syncClock;readonly Dictionary<int,DistrictView> districts=new Dictionary<int,DistrictView>();readonly Dictionary<string,Transform> cityRoots=new Dictionary<string,Transform>();readonly Dictionary<int,Transform> cityTraffic=new Dictionary<int,Transform>();
 sealed class Traffic {public string key;public OrbitDemo.State state;public Transform root;public int destination;}
 readonly List<Traffic> traffic=new List<Traffic>();readonly Dictionary<int,Transform> rivalCities=new Dictionary<int,Transform>();readonly List<Light> cityLights=new List<Light>();readonly List<Mesh> roadMeshes=new List<Mesh>();
 Transform ghost,dysonRoot,previewRoot,previewModel;Camera previewCamera;RenderTexture previewTexture;int ghostKind=-1,dysonCount=-1,dysonSystem=-1;Material ghostMaterial;readonly List<Transform> collectors=new List<Transform>();Material previewPaint;
 public Texture PreviewTexture{get{return previewTexture;}}
 public Vector3 DistrictPosition(int id){return districts[id].root.position;}
 public int DistrictViews{get{return districts.Count;}}public int CollectorViews{get{return collectors.Count;}}
 public void Initialize(DefenseGame owner,FrontierArt painter,PlanetExpedition expedition){game=owner;art=painter;ground=expedition;previewRoot=new GameObject("FRONTIER / isolated 3D diorama").transform;previewRoot.position=new Vector3(0,-40000,0);previewTexture=new RenderTexture(1024,768,24);previewTexture.Create();previewCamera=new GameObject("Shipwright / design camera").AddComponent<Camera>();previewCamera.cullingMask=1<<28;previewCamera.clearFlags=CameraClearFlags.SolidColor;previewCamera.backgroundColor=new Color(.018f,.033f,.055f);previewCamera.fieldOfView=33;previewCamera.nearClipPlane=.05f;previewCamera.farClipPlane=800;previewCamera.targetTexture=previewTexture;previewCamera.enabled=false;previewCamera.gameObject.AddComponent<UniversalAdditionalCameraData>().renderPostProcessing=true;Camera.main.cullingMask&=~(1<<28);var lamp=new GameObject("Diorama / soft key").AddComponent<Light>();lamp.type=LightType.Directional;lamp.transform.rotation=Quaternion.Euler(45,25,0);lamp.cullingMask=1<<28;lamp.color=new Color(.68f,.85f,1);lamp.intensity=.85f;lamp.transform.SetParent(previewRoot,false);}
 Vector3 Surface(PlanetExpedition.Planet p,Vector3 n){return n*((float)p.body.radius+PlanetExpedition.Height(n,p.body.seed,p.body.radius));}
 public void Sync(CivilizationModel model,Vector3 focus){state=model;var alive=new HashSet<int>();foreach(var colony in model.colonies)foreach(var d in colony.districts)alive.Add(d.id);var stale=new List<int>();foreach(var pair in districts)if(!alive.Contains(pair.Key)){Destroy(pair.Value.root.gameObject);stale.Add(pair.Key);}foreach(int id in stale)districts.Remove(id);foreach(var pair in cityRoots)if(model.Find(pair.Key)==null)pair.Value.gameObject.SetActive(false);foreach(var c in model.colonies){var p=ground.planets.Find(x=>x.key==c.key);if(p==null){if(cityRoots.TryGetValue(c.key,out var hidden))hidden.gameObject.SetActive(false);continue;}if(!cityRoots.TryGetValue(c.key,out var root)){root=new GameObject(c.name+" / PERSISTENT CIVILIZATION").transform;cityRoots.Add(c.key,root);}root.gameObject.SetActive(Vector3.Distance(focus,p.body.P)<p.body.radius+16000);root.position=p.body.P;
   foreach(var d in c.districts){if(!districts.TryGetValue(d.id,out var view)){var district=art.District(root,d.kind);view=new DistrictView{data=d,root=district};districts.Add(d.id,view);if(d.kind==0&&cityLights.Count<8){var lamp=new GameObject("City / landing plaza illumination").AddComponent<Light>();lamp.transform.SetParent(district,false);lamp.transform.localPosition=new Vector3(0,13,10);lamp.type=LightType.Point;lamp.range=38;lamp.intensity=160;lamp.color=new Color(.18f,.65f,1);cityLights.Add(lamp);}if(d.kind!=0)BuildRoad(root,p,c.anchor,d.normal);}
    view.root.localPosition=Surface(p,d.normal);view.root.localRotation=Quaternion.FromToRotation(Vector3.up,d.normal)*Quaternion.Euler(0,d.yaw,0);view.root.localScale=new Vector3(1,Mathf.Lerp(.025f,1,Mathf.SmoothStep(0,1,d.progress)),1);
    if(d.kind==5){bool show=c.rockets>0||c.fabricating;if(show&&view.rocket==null){view.rocket=art.Rocket(view.root);view.rocket.localPosition=Vector3.up*.6f;}if(view.rocket!=null){view.rocket.gameObject.SetActive(show);view.rocket.localScale=Vector3.one*(c.fabricating?Mathf.Lerp(.05f,1,c.rocketWork):1);}}
   }
  }
  SyncRivals(model,focus);SyncTraffic(model,focus);SyncDyson(model);
 }
 void BuildRoad(Transform parent,PlanetExpedition.Planet p,Vector3 from,Vector3 to){var vertices=new List<Vector3>();var normals=new List<Vector3>();var triangles=new List<int>();for(int i=0;i<=48;i++){Vector3 n=Vector3.Slerp(from,to,i/48f).normalized;Vector3 tangent=Vector3.ProjectOnPlane(to-from,n).normalized;Vector3 side=Vector3.Cross(n,tangent).normalized;Vector3 center=Surface(p,n)+n*.45f;vertices.Add(center-side*1.7f);vertices.Add(center+side*1.7f);normals.Add(n);normals.Add(n);if(i<48){int k=i*2;triangles.AddRange(new[]{k,k+2,k+1,k+1,k+2,k+3});}}var mesh=new Mesh{name="Terrain fitted city transit paving"};mesh.SetVertices(vertices);mesh.SetNormals(normals);mesh.SetTriangles(triangles,0);mesh.RecalculateBounds();roadMeshes.Add(mesh);var road=new GameObject("City / terrain fitted transit link");road.transform.SetParent(parent,false);road.AddComponent<MeshFilter>().sharedMesh=mesh;var renderer=road.AddComponent<MeshRenderer>();renderer.sharedMaterial=art.armor;renderer.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;renderer.receiveShadows=false;}
 void SyncRivals(CivilizationModel model,Vector3 focus){for(int i=0;i<model.factions.Count;i++){var f=model.factions[i];var p=ground.planets.Find(x=>game.CivilPortKey(f.port)==x.key);bool owned=model.colonies.Exists(c=>c.port==f.port);if(p==null||owned){if(rivalCities.TryGetValue(i,out var hidden))hidden.gameObject.SetActive(false);continue;}if(!rivalCities.TryGetValue(i,out var root)){root=new GameObject(f.name+" / rival planetary capital").transform;rivalCities.Add(i,root);if(i==0){art.District(root,0);var hab=art.District(root,1);hab.localPosition=new Vector3(64,0,0);var solar=art.District(root,3);solar.localPosition=new Vector3(-56,0,0);}else art.AlienCity(root,i);}root.gameObject.SetActive(Vector3.Distance(focus,p.body.P)<p.body.radius+16000);Vector3 n=new Vector3(.18f,.94f,-.29f).normalized;root.position=p.body.P+Surface(p,n);root.rotation=Quaternion.FromToRotation(Vector3.up,n);}}
 void SyncTraffic(CivilizationModel model,Vector3 focus){for(int i=traffic.Count-1;i>=0;i--){var t=traffic[i];var c=model.Find(t.key);var p=ground.planets.Find(x=>x.key==t.key);if(c==null||p==null||Vector3.Distance(focus,p.body.P+c.anchor*(float)p.body.radius)>2100){Destroy(t.root.gameObject);traffic.RemoveAt(i);}}foreach(var c in model.colonies){if(c.districts.Count<2||traffic.Count>=12)continue;var p=ground.planets.Find(x=>x.key==c.key);if(p==null||Vector3.Distance(focus,p.body.P+c.anchor*(float)p.body.radius)>2000)continue;int count=traffic.FindAll(t=>t.key==c.key).Count;for(int i=count;i<3;i++){Vector3 at=p.body.P+Surface(p,c.anchor)+c.anchor*(48+i*7);var root=art.Hull(null,0);root.name="Civilian / autonomous city shuttle";root.localScale=Vector3.one*.65f;traffic.Add(new Traffic{key=c.key,root=root,state=new OrbitDemo.State{x=at.x,y=at.y,z=at.z},destination=i%c.districts.Count});}}}
 void TrafficTick(float dt){foreach(var t in traffic){var c=state.Find(t.key);var p=ground.planets.Find(x=>x.key==t.key);if(c==null||p==null)continue;Vector3 normal=c.districts[t.destination%c.districts.Count].normal,target=p.body.P+Surface(p,normal)+normal*52,at=DefenseGame.Pos(t.state),delta=target-at;if(delta.magnitude<8)t.destination=(t.destination+1)%c.districts.Count;Vector3 desired=Vector3.ClampMagnitude(delta*.6f,18);Vector3 force=(desired-DefenseGame.Vel(t.state))*3-DefenseGame.Gravity(at);for(float elapsed=0;elapsed<dt-.00001f;elapsed+=.01f)DefenseGame.Step(ref t.state,force,Mathf.Min(.01f,dt-elapsed));t.root.position=DefenseGame.Pos(t.state);if(delta.sqrMagnitude>1)t.root.rotation=Quaternion.Slerp(t.root.rotation,Quaternion.LookRotation(delta,normal),dt*3);}}
 void SyncDyson(CivilizationModel model){int count=model.dysonBuilt+(model.dysonWorking?1:0);if(count==0){if(dysonRoot!=null)dysonRoot.gameObject.SetActive(false);return;}if(dysonRoot==null||dysonSystem!=model.dysonSystem){if(dysonRoot!=null)Destroy(dysonRoot.gameObject);dysonRoot=new GameObject("DYSON / stellar collector shell").transform;collectors.Clear();dysonCount=-1;dysonSystem=model.dysonSystem;for(int row=-2;row<=2;row++){float latitude=row*.36f;float y=Mathf.Sin(latitude)*4200,r=Mathf.Cos(latitude)*4200;var rail=new GameObject("Orbital collector truss / ring "+row).AddComponent<LineRenderer>();rail.transform.SetParent(dysonRoot,false);rail.useWorldSpace=false;rail.loop=true;rail.positionCount=192;rail.widthMultiplier=5;rail.sharedMaterial=art.beamOrange;for(int j=0;j<192;j++){float angle=j*Mathf.PI*2/192;rail.SetPosition(j,new Vector3(Mathf.Cos(angle)*r,y,Mathf.Sin(angle)*r));}}}
  dysonRoot.gameObject.SetActive(true);dysonRoot.position=game.CivilStarPosition(model.dysonSystem);if(dysonCount!=count){for(int i=collectors.Count;i<count;i++)collectors.Add(art.Collector(dysonRoot,i,12,4200));dysonCount=count;}for(int i=0;i<collectors.Count;i++){float scale=i<model.dysonBuilt?1:Mathf.Lerp(.1f,1,model.dysonWork);collectors[i].localScale=Vector3.one*scale;}
 }
 public void Tick(float dt,CivilizationModel model,Vector3 focus,bool active){syncClock-=dt;if(syncClock<=0){Sync(model,focus);syncClock=.35f;}if(active)TrafficTick(dt);foreach(var lamp in cityLights)if(lamp!=null)lamp.enabled=Vector3.Distance(focus,lamp.transform.position)<350;if(previewModel!=null&&previewCamera.enabled)previewModel.Rotate(0,Time.unscaledDeltaTime*9,0,Space.Self);if(dysonRoot!=null&&active)dysonRoot.Rotate(0,dt*.12f,0,Space.Self);}
 public void Shift(Vector3 shift){foreach(var c in cityRoots.Values)c.position-=shift;foreach(var c in rivalCities.Values)c.position-=shift;foreach(var t in traffic){t.state.x-=shift.x;t.state.y-=shift.y;t.state.z-=shift.z;t.root.position-=shift;}if(ghost!=null)ghost.position-=shift;if(dysonRoot!=null)dysonRoot.position-=shift;}
 public void Ghost(PlanetExpedition.Planet p,Vector3 normal,int kind,float yaw,bool valid){if(ghost==null||ghostKind!=kind){if(ghost!=null)Destroy(ghost.gameObject);ghostKind=kind;ghost=art.District(null,kind);if(ghostMaterial!=null)Destroy(ghostMaterial);ghostMaterial=new Material(Shader.Find("Orbit/Glow"));foreach(var r in ghost.GetComponentsInChildren<Renderer>())r.sharedMaterial=ghostMaterial;}ghost.gameObject.SetActive(true);ghostMaterial.SetColor("_Color",valid?new Color(.04f,.5f,.4f,.35f):new Color(.65f,.06f,.13f,.35f));ghost.position=p.body.P+Surface(p,normal);ghost.rotation=Quaternion.FromToRotation(Vector3.up,normal)*Quaternion.Euler(0,yaw,0);}
 public void HideGhost(){if(ghost!=null)ghost.gameObject.SetActive(false);}
 public void Preview(int tab,int selection,int paint,CivilizationModel model){if(previewModel!=null)Destroy(previewModel.gameObject);if(previewPaint!=null)Destroy(previewPaint);previewCamera.enabled=true;previewPaint=art.Coating(paint);previewModel=new GameObject("Interactive 3D design").transform;previewModel.SetParent(previewRoot,false);float size=9,height=.2f;
  if(tab==2){art.District(previewModel,selection,28);size=100;height=12;}
  else if(tab==5){var sun=GameObject.CreatePrimitive(PrimitiveType.Sphere);Destroy(sun.GetComponent<Collider>());sun.layer=28;sun.transform.SetParent(previewModel,false);sun.transform.localScale=Vector3.one*24;sun.GetComponent<Renderer>().sharedMaterial=art.star;for(int i=0;i<Mathf.Max(1,model.dysonBuilt+(model.dysonWorking?1:0));i++)art.Collector(previewModel,i,12,29,28);size=110;height=0;}
  else {int hull=tab==3?selection:tab==4?3:model.blueprint;art.Hull(previewModel,hull,previewPaint,28);size=hull==0?5.6f:hull==3?9:7.0f;var floor=GameObject.CreatePrimitive(PrimitiveType.Cube);Destroy(floor.GetComponent<Collider>());floor.name="Shipwright / studio floor";floor.layer=28;floor.transform.SetParent(previewModel,false);floor.transform.localPosition=Vector3.down*1.15f;floor.transform.localScale=new Vector3(size*1.2f,.07f,size*1.4f);floor.GetComponent<Renderer>().sharedMaterial=art.dark;for(int i=-4;i<=4;i++){var grid=new GameObject("Diorama / metric guide").AddComponent<LineRenderer>();grid.gameObject.layer=28;grid.transform.SetParent(previewModel,false);grid.useWorldSpace=false;grid.positionCount=2;grid.widthMultiplier=.014f;grid.sharedMaterial=art.beamCyan;grid.SetPositions(new[]{new Vector3(i*size*.10f,-1.1f,-size*.6f),new Vector3(i*size*.10f,-1.1f,size*.6f)});}}
  previewCamera.transform.position=previewRoot.position+new Vector3(size*.58f,height+size*.26f,-size);previewCamera.transform.LookAt(previewRoot.position+Vector3.up*height);previewModel.rotation=Quaternion.Euler(0,145,0);
 }
 public void AnimatePreview(float dt,Vector2 stick){if(previewModel!=null&&previewCamera.enabled)previewModel.Rotate(stick.y*dt*25,(9+stick.x*75)*dt,0,Space.Self);}
 public void ResetTraffic(){foreach(var t in traffic)if(t.root!=null)Destroy(t.root.gameObject);traffic.Clear();syncClock=0;}
 public void HidePreview(){if(previewCamera!=null)previewCamera.enabled=false;}
 public Vector3 Resolve(Vector3 point,float radius){foreach(var view in districts.Values){if(view.root==null||!view.root.gameObject.activeInHierarchy||view.data.progress<.25f||Vector3.Distance(point,view.root.position)>65)continue;Vector3 p=view.root.InverseTransformPoint(point);if(p.y<-.5f||p.y>38)continue;int kind=view.data.kind;
   if(kind==1){for(int j=0;j<6;j++){float a=j*Mathf.PI/3;p=Circle(p,new Vector3(Mathf.Cos(a)*13,0,Mathf.Sin(a)*13),4.7f+radius);}}
   else if(kind==2){for(int j=0;j<3;j++)p=Circle(p,new Vector3(-10+j*10,0,0),3.6f+radius);}
   else if(kind==5){for(int side=-1;side<=1;side+=2)p=Circle(p,new Vector3(side*19,0,-12),2.5f+radius);p=Circle(p,new Vector3(0,0,-19),9+radius);}
   else if(kind==6){for(int side=-1;side<=1;side+=2)p=Circle(p,new Vector3(side*20,0,0),4+radius);}
   else if(kind!=3)p=Circle(p,Vector3.zero,(kind==0?6.5f:kind==4?10:9)+radius);
   point=view.root.TransformPoint(p);
  }return point;}
 static Vector3 Circle(Vector3 p,Vector3 center,float radius){Vector3 d=new Vector3(p.x-center.x,0,p.z-center.z);if(d.sqrMagnitude<radius*radius){if(d.sqrMagnitude<.001f)d=Vector3.forward;d=d.normalized*radius;p.x=center.x+d.x;p.z=center.z+d.z;}return p;}
 void OnDestroy(){if(previewCamera!=null)Destroy(previewCamera.gameObject);if(previewRoot!=null)Destroy(previewRoot.gameObject);if(previewTexture!=null){previewTexture.Release();Destroy(previewTexture);}if(ghost!=null)Destroy(ghost.gameObject);if(ghostMaterial!=null)Destroy(ghostMaterial);if(previewPaint!=null)Destroy(previewPaint);if(dysonRoot!=null)Destroy(dysonRoot.gameObject);foreach(var r in cityRoots.Values)if(r!=null)Destroy(r.gameObject);foreach(var r in rivalCities.Values)if(r!=null)Destroy(r.gameObject);foreach(var t in traffic)if(t.root!=null)Destroy(t.root.gameObject);foreach(var mesh in roadMeshes)if(mesh!=null)Destroy(mesh);if(art!=null)art.Dispose();}
}
